"""Generate docs/database-schema.md from the SQLAlchemy models and the grant matrix.
Usage: make docs-schema"""

from __future__ import annotations

import inspect

from netguard_common.grants import GRANTS
from netguard_common.models import Base


def main() -> None:
    purposes = {
        m.local_table.name: inspect.cleandoc(m.class_.__doc__ or "").replace("\n", " ")
        for m in Base.registry.mappers
    }
    out = [
        "# Database schema reference",
        "",
        "Generated by `make docs-schema` from `netguard_common.models` "
        "and `netguard_common.grants`. "
        "Do not edit by hand. Migrations in `migrations/` are the deployed source of truth; "
        "`make migrate-check` fails if they drift from the models.",
        "",
        "Conventions: all timestamps are `timestamptz` (UTC); addresses are `inet`/`macaddr`; "
        "enumerations are text with a named CHECK; the monitor and API roles hold only the "
        "privileges listed per table.",
        "",
    ]
    for name in sorted(Base.metadata.tables):
        t = Base.metadata.tables[name]
        out += [f"## `{name}`", ""]
        if purposes.get(name):
            out += [purposes[name], ""]
        out += ["| Column | Type | Null | Default |", "|---|---|---|---|"]
        for c in t.columns:
            default = ""
            if c.server_default is not None:
                default = str(getattr(c.server_default, "arg", c.server_default))
            if c.computed is not None:
                default = f"generated: {c.computed.sqltext}"
            if c.identity is not None:
                default = "identity"
            pk = " (PK)" if c.primary_key else ""
            out.append(
                f"| `{c.name}`{pk} | {c.type.compile(dialect=_dialect())} | "
                f"{'yes' if c.nullable else 'no'} | {default.replace('|', '/')} |"
            )
        idx = sorted(t.indexes, key=lambda i: i.name or "")
        if idx:
            out += ["", "Indexes:"]
            for i in idx:
                cols = ", ".join(str(e).replace("\n", " ") for e in i.expressions)
                where = i.dialect_options["postgresql"]["where"]
                out.append(
                    f"- `{i.name}` on ({cols})"
                    + (" UNIQUE" if i.unique else "")
                    + (f" WHERE {where}" if where is not None else "")
                )
        checks = sorted(
            c.name for c in t.constraints if c.__class__.__name__ == "CheckConstraint" and c.name
        )
        if checks:
            out += ["", "Checks: " + ", ".join(f"`{c}`" for c in checks)]
        g = GRANTS.get(name, {})
        out += [
            "",
            "Runtime privileges: "
            + (
                "; ".join(f"**{r}**: {', '.join(p)}" for r, p in g.items())
                or "none (migrator only)"
            ),
            "",
        ]
    print("\n".join(out))


def _dialect():  # type: ignore[no-untyped-def]
    from sqlalchemy.dialects import postgresql

    return postgresql.dialect()


if __name__ == "__main__":
    main()
